package com.on.turip.feature.popularregion.impl.map

/**
 * 시도 행정경계 폴리곤.
 *
 * 통계청 2018년 시도 경계(TopoJSON)를 모바일용으로 줄인 것이다.
 * 링이 아니라 **공유 아크** 단위로 단순화해, 맞닿은 시도의 경계선이 양쪽에서 똑같이 줄어든다.
 * 링을 따로 줄이면 인접 경계가 어긋나 지도에 실금 같은 틈이 생긴다.
 *
 * 18만 점을 2,934점으로 줄였고(원본의 1.6%), 화면 1dp 남짓의 오차만 남는다.
 * 면적이 아주 작은 섬은 이 크기에서 점 하나로 뭉개지므로 뺐다.
 *
 * 좌표 형식은 [decodeRings] 참고. 지역 하나가 문자열 하나다.
 *
 * 여기에는 실제 행정구역 17개만 둔다.
 * 통합시처럼 여러 시도를 합친 지역은 [shapesOf] 가 구성 지역의 링을 이어 붙여 만든다.
 */
internal object KoreaRegionShapes {
    /**
     * 경계를 갖고 있는 시도 코드.
     *
     * 방문자 수가 오기 전에도 지도 모양은 그릴 수 있어야 해서, 응답과 무관하게 아는 지역을 알려 준다.
     */
    val areaCodes: Set<Int> get() = ENCODED_SHAPES.keys

    /**
     * [areaCode] 의 외곽 링 목록. 지도에 놓을 경계가 없으면 빈 목록이다.
     *
     * 통합시는 흡수한 시도의 링을 모두 합쳐 돌려준다. 합친 링을 그대로 그리면 옛 경계가
     * 안쪽에 실선으로 남으므로, 그리는 쪽에서 하나의 도형으로 합집합을 낸 뒤 테두리를 그린다.
     */
    fun shapesOf(areaCode: Int): List<List<GeoPoint>> =
        SidoAreas
            .mergedAreaCodesOf(areaCode)
            .flatMap { decoded[it].orEmpty() }

    private val decoded: Map<Int, List<List<GeoPoint>>> by lazy {
        ENCODED_SHAPES.mapValues { (_, encoded) -> encoded.decodeRings() }
    }

